const cursor = $json.data && $json.data.cursor ? String($json.data.cursor) : null;

// The cursor is stored in epoch SECONDS. Gmail's `after:` operator also uses
// seconds. We re-read one second before the cursor to avoid losing messages
// that share the boundary timestamp; the backend deduplicates by message id.
let q = 'newer_than:1d';
if (cursor && /^\d+$/.test(cursor)) {
  const from = Math.max(0, Number(cursor) - 1);
  q = 'after:' + from;
}

return [{ json: { q, cursorStart: cursor } }];

const items = $input.all();

const headersOf = (m) => (m.payload && m.payload.headers) || [];
const getHeader = (headers, name) => {
  const found = headers.find(h => String(h.name).toLowerCase() === name);
  return found ? found.value : '';
};
const decode = (data) => Buffer.from(data || '', 'base64').toString('utf-8');
const bodyOf = (m) => {
  const parts = (m.payload && m.payload.parts) || [];
  if (m.text) return m.text;
  const plain = parts.find(p => p.mimeType === 'text/plain' && p.body && p.body.data);
  if (plain) return decode(plain.body.data);
  return m.snippet || '';
};

let cursorEnd = 0;
const messages = [];

for (const item of items) {
  const m = item.json || {};
  if (!m.id) continue;
  const headers = headersOf(m);
  const internalSeconds = Math.floor(Number(m.internalDate || Date.now()) / 1000);
  if (internalSeconds > cursorEnd) cursorEnd = internalSeconds;

  const recipients = [getHeader(headers, 'to'), getHeader(headers, 'cc'), getHeader(headers, 'bcc')]
    .filter(Boolean)
    .join(',')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);

  messages.push({
    gmailMessageId: m.id,
    gmailThreadId: m.threadId,
    sender: getHeader(headers, 'from'),
    recipients,
    subject: getHeader(headers, 'subject'),
    bodyText: String(bodyOf(m)).slice(0, 400000),
    receivedAt: new Date(internalSeconds * 1000).toISOString()
  });
}

if (messages.length === 0) {
  return [];
}

// Chunk into batches the backend accepts (max 100).
const CHUNK = 50;
const chunks = [];
for (let i = 0; i < messages.length; i += CHUNK) {
  const isLast = i + CHUNK >= messages.length;
  chunks.push({
    json: {
      mailbox: $env.MAILBOX_ADDRESS,
      // Advance the durable cursor only on the final chunk: if an earlier
      // chunk fails, the workflow stops and the cursor stays put, so the
      // next run retries the whole window (dedup absorbs the overlap).
      cursor: isLast && cursorEnd ? String(cursorEnd) : null,
      executionId: $execution.id,
      messages: messages.slice(i, i + CHUNK),
      _cursorEnd: cursorEnd ? String(cursorEnd) : null
    }
  });
}

return chunks;

const responses = $input.all();
let imported = 0;
let skipped = 0;
for (const r of responses) {
  const d = (r.json && r.json.data) || {};
  imported += Number(d.imported || 0);
  skipped += Number(d.skipped || 0);
}
const first = $('Normaliser et découper').first().json;
return [{ json: {
  mailbox: $env.MAILBOX_ADDRESS,
  executionId: $execution.id,
  status: 'SUCCESS',
  cursorStart: $('Calculer la requête').first().json.cursorStart,
  cursorEnd: first._cursorEnd || null,
  importedCount: imported,
  updatedCount: 0,
  skippedCount: skipped,
  failedCount: 0
} }];
